svg.script:
var svgRoot = document.documentElement;
var detailButtons = [].slice.call(document.querySelectorAll(".details-toggle"));
var overviewButtons = [].slice.call(document.querySelectorAll(".overview-toggle"));
function setPanelMode(panelId, showDetails) {
  ["1", "2", "3"].forEach(function(id) {
    svgRoot.classList.remove("details-panel-" + id);
  });
  if (showDetails) svgRoot.classList.add("details-panel-" + panelId);
  detailButtons.forEach(function(button) {
    button.setAttribute("aria-expanded", String(showDetails && button.dataset.panel === panelId));
  });
  overviewButtons.forEach(function(button) {
    button.setAttribute("aria-expanded", String(!showDetails && button.dataset.panel === panelId));
  });
}
detailButtons.forEach(function(button) {
  button.addEventListener("click", function() { setPanelMode(button.dataset.panel, true); });
  button.addEventListener("keydown", function(event) {
    if (event.key === "Enter" || event.key === " ") { event.preventDefault(); setPanelMode(button.dataset.panel, true); }
  });
});
overviewButtons.forEach(function(button) {
  button.addEventListener("click", function() { setPanelMode(button.dataset.panel, false); });
  button.addEventListener("keydown", function(event) {
    if (event.key === "Enter" || event.key === " ") { event.preventDefault(); setPanelMode(button.dataset.panel, false); }
  });
});
